  function bloquearTela() {
    if (_telaBloqueada) return;
    _telaBloqueada = true;
    const pin = dataStore.dados.config.pin;
    if (!pin) return;
    let tentativas = 0;
    function mostrarPinModal() {
      let entrada = "";
      const render = () => {
        abrirModal(`<h3><i class="fas fa-lock"></i> Tela Bloqueada</h3><p style="font-size:0.85rem;color:var(--text-muted);margin-bottom:8px;">Digite seu PIN de 4 d\xEDgitos para continuar</p><div class="pin-display">${"\u2022".repeat(entrada.length).padEnd(4, "_")}</div>${tentativas > 0 ? '<p style="color:#ef4444;font-size:0.8rem;">PIN incorreto. Tente novamente.</p>' : ""}<div class="pin-pad">${[1, 2, 3, 4, 5, 6, 7, 8, 9, "", 0, "\u232B"].map((v) => v === "" ? "<button disabled></button>" : `<button data-val="${v}">${v}</button>`).join("")}</div><div class="modal-acoes"><button class="btn-secundario" id="btnSairPin">Sair</button></div>`);
        document.querySelectorAll(".pin-pad button[data-val]").forEach((btn) => {
          btn.addEventListener("click", () => {
            if (btn.dataset.val === "\u232B") {
              entrada = entrada.slice(0, -1);
              render();
              return;
            }
            if (entrada.length >= 4) return;
            entrada += btn.dataset.val;
            if (entrada.length === 4) {
              if (entrada === pin) {
                _telaBloqueada = false;
                fecharModal();
                mostrarToast("Bem-vindo de volta!", "sucesso");
                iniciarMonitorInatividade();
              } else {
                tentativas++;
                entrada = "";
                render();
              }
            } else {
              render();
            }
          });
        });
        document.getElementById("btnSairPin")?.addEventListener("click", () => {
          fecharModal();
        });
        document.getElementById("btnCancelarModal")?.addEventListener("click", fecharModal);
      };
      render();
    }
    mostrarPinModal();
  }
  function dispararConfetti() {
    const canvas = document.createElement("canvas");
    canvas.className = "confetti-canvas";
    document.body.appendChild(canvas);
    const ctx = canvas.getContext("2d");
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    const particles = Array.from({ length: 80 }, () => ({
      x: canvas.width / 2 + (Math.random() - 0.5) * 200,
      y: canvas.height / 2,
      vx: (Math.random() - 0.5) * 8,
      vy: -Math.random() * 10 - 4,
      size: Math.random() * 6 + 3,
      color: ["#ff0", "#f0f", "#0ff", "#f00", "#0f0", "#00f", "#ffa500", "#ff69b4"][Math.floor(Math.random() * 8)],
      rotation: Math.random() * 360,
      rotSpeed: (Math.random() - 0.5) * 10,
      gravity: 0.2 + Math.random() * 0.1
    }));
    let frame = 0;
    const anim = () => {
      frame++;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particles.forEach((p) => {
        p.x += p.vx;
        p.y += p.vy;
        p.vy += p.gravity;
        p.rotation += p.rotSpeed;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rotation * Math.PI / 180);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
        ctx.restore();
      });
      if (frame < 90) requestAnimationFrame(anim);
      else canvas.remove();
    };
    anim();
  }
